package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/vaults/{vaultId}/sync") public class PasswordSyncController{private final PasswordSyncService service;public PasswordSyncController(PasswordSyncService s){service=s;}@GetMapping public Mono<PasswordSyncView> sync(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@RequestParam(required=false)Instant cursor){return service.sync(a,vaultId,cursor);}}
